+                    n.add(im1.multiply(xToI))
+                        .setScale(sp1, BigDecimal.ROUND_HALF_EVEN);
+            // (index*(x^(index-1))
+            BigDecimal denominator =
+                    i.multiply(xToIm1)
+                        .setScale(sp1, BigDecimal.ROUND_HALF_EVEN);
+            // x = (n + (index-1)*(x^index)) / (index*(x^(index-1)))
+            xPrev = x;
+            x = numerator
+                    .divide(denominator, sp1, BigDecimal.ROUND_DOWN);
