+     * @param x the value of x
+     * @param scale the desired scale of the result
+     * @return the result value
+     */
+    public static BigDecimal exp(BigDecimal x, int scale)
+    {
+        // e^0 = 1
+        if (x.signum() == 0) {
+            return BigDecimal.valueOf(1);
